head.script:
scwin.onpageload = function () {
    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 기존 target 있으면 삭제
    if (typeof target2 !== 'undefined') {
        target2.remove();
    }

    // 조건 설정   
    let properties = {    
        placeholderLocaleRef: wf_sample.getObj("con_placeholderLocaleRef").getText(),
        useLocale: wf_sample.getObj("con_useLocale").getText(),
        style: 'width:200px;height:30px;',
    };

    let cList = $c.gcm.createCList(properties);    

    $c.gcm.createEmptyInput(cList, 'ev:onclick="scwin.target1_onclick"');
}
